/* DAZK · the order on the "Cotizar" step: several pieces, chairs and stools, the client's name and WhatsApp, and sending it to the workshop. */
window.addEventListener('DOMContentLoaded', function () {
  const $ = s => document.querySelector(s), A = window.DAZK_API, D = window.DAZK, esc = A.esc;
  let cart = A.load('dazk-cart', []), skipCur = false;
  const extra = {}, NOMBRE = {};
  const yo = A.load('dazk-yo', {}), mine = () => A.load('dazk-pedidos', []);

  // everything that goes in the order: saved pieces, the one on screen, and seats
  function items() {
    const out = cart.slice(); if (!skipCur) out.push(window.DAZK_ITEM());
    Object.keys(extra).forEach(k => { if (extra[k]) out.push({ tipo: k, titulo: NOMBRE[k], cantidad: extra[k], specs: [['Modelo y tapiz', 'Por definir con DAZK']] }); });
    return out;
  }
  function draw() {
    const cur = window.DAZK_ITEM();
    $('#cart').innerHTML = cart.map((it, i) => `<li><span>${esc(it.titulo)}</span><button type="button" data-rm="${i}" aria-label="Quitar ${esc(it.titulo)}">Quitar</button></li>`).join('') +
      (skipCur ? '' : `<li class="cur"><span>${esc(cur.titulo)}<small>La que estás viendo en 3D</small></span>${cart.length ? '<button type="button" data-rm="cur" aria-label="Quitar esta mesa">Quitar</button>' : ''}</li>`);
    Object.keys(extra).forEach(k => { $('#x-' + k).textContent = extra[k]; });
    const n = items().length; $('#sendbar').textContent = !$('#p-ok').hidden ? 'Ver mi pedido' : n > 1 ? 'Apartar (' + n + ')' : 'Apartar';
  }
  $('#cart').addEventListener('click', e => {
    const b = e.target.closest('[data-rm]'); if (!b) return;
    if (b.dataset.rm === 'cur') skipCur = true; else cart.splice(+b.dataset.rm, 1);
    if (!cart.length) skipCur = false;
    A.save('dazk-cart', cart); draw();
  });
  $('#add-more').addEventListener('click', () => {
    if (!skipCur) cart.push(window.DAZK_ITEM());
    skipCur = false; A.save('dazk-cart', cart); draw();
    window.DAZK_WELCOME('Guardamos esa pieza en tu pedido. ¿Qué más quieres crear?');
  });
  document.querySelectorAll('[data-x]').forEach(b => b.addEventListener('click', () => {
    const k = b.dataset.x; extra[k] = Math.max(0, Math.min(40, extra[k] + (+b.dataset.d))); draw();
  }));
  // any change to the table on screen brings it back into the order
  const sync0 = window.DAZK_ONSYNC; let lastLink = '';
  window.DAZK_ONSYNC = function () {
    if (sync0) sync0.apply(this, arguments);
    const l = window.DAZK_LINK(); if (l !== lastLink) { if (lastLink) skipCur = false; lastLink = l; }
    draw();
  };

  // ---- who is ordering ----
  $('#p-nombre').value = yo.nombre || ''; $('#p-tel').value = yo.tel || '';
  function hello() {
    const n = (A.load('dazk-yo', {}).nombre || '').split(' ')[0], k = mine().length;
    const h = $('#w-hi'); h.hidden = !n; h.textContent = n ? 'Hola de nuevo, ' + n + '.' : '';
    document.querySelectorAll('[data-mis]').forEach(a => { a.hidden = !k; a.textContent = k > 1 ? 'Mis pedidos (' + k + ')' : 'Mi pedido'; a.href = k === 1 ? A.seguimiento(mine()[0].token) : 'pedido.html'; });
  }
  hello();

  // ---- send ----
  const form = $('#f-ped'), err = $('#p-err'), btn = $('#enviar');
  function fail(t, el) { err.textContent = t; err.hidden = false; if (el) el.focus(); }
  form.addEventListener('submit', async e => {
    e.preventDefault(); err.hidden = true;
    const nombre = $('#p-nombre').value.trim(), tel = $('#p-tel').value.replace(/\D/g, '');
    if (nombre.length < 2) return fail('Escribe a nombre de quién apartamos la mesa.', $('#p-nombre'));
    if (tel && (tel.length < 10 || tel.length > 13)) return fail('Tu WhatsApp debe tener 10 dígitos, o déjalo vacío.', $('#p-tel'));
    const its = items(), label = btn.textContent; btn.disabled = true; btn.textContent = 'Enviando…';
    try {
      const r = await A.crearPedido({ nombre, tel, notas: $('#notas').value, items: its, canal: A.load('dazk-canal', '') });
      A.save('dazk-yo', Object.assign({ nombre }, tel ? { tel } : {}));
      A.save('dazk-pedidos', [{ folio: r.folio, token: r.token, fecha: new Date().toISOString() }].concat(mine()));
      cart = []; A.save('dazk-cart', cart); if (window.DAZK_VISITA) window.DAZK_VISITA(r.folio);
      const link = A.seguimiento(r.token);
      const msg = `Hola DAZK, soy ${nombre}. Acabo de apartar mi pedido #${r.folio}:\n` + its.map(i => `• ${i.cantidad > 1 ? i.cantidad + ' × ' : ''}${i.titulo}`).join('\n') + `\n\nSeguimiento: ${link}`;
      $('#ok-folio').textContent = '#' + r.folio; $('#ok-nombre').textContent = nombre.split(' ')[0];
      $('#ok-link').href = link;
      $('#ok-wa').innerHTML = D.wa.map((w, i) => `<a class="btn ${i ? '' : 'wa big'}" target="_blank" rel="noopener" href="https://wa.me/${w.num}?text=${encodeURIComponent(msg)}">${i ? 'O a ' + esc(w.label) : 'Mandar mi folio por WhatsApp'}</a>`).join('');
      $('#p-box').hidden = true; $('#p-ok').hidden = false; draw();
      $('#p-ok').scrollIntoView({ behavior: 'smooth', block: 'center' }); hello();
    } catch (ex) { fail(ex.message || 'No se pudo enviar. Intenta de nuevo.'); }
    finally { btn.disabled = false; btn.textContent = label; }
  });
  $('#sendbar').addEventListener('click', () => { if ($('#p-ok').hidden) { form.scrollIntoView({ behavior: 'smooth', block: 'center' }); form.requestSubmit(); } else location.href = $('#ok-link').href; });
  $('#ok-new').addEventListener('click', () => { $('#p-ok').hidden = true; $('#p-box').hidden = false; draw(); window.DAZK_WELCOME(''); });
  draw();

  // ---- reviews from real clients, published by DAZK ----
  // the owner's settings from the panel: last known copy first, then the live one
  if (window.DAZK_PUBLICO) {
    const c0 = A.load('dazk-publico', null); if (c0) window.DAZK_PUBLICO(c0);
    A.publico().then(c => { A.save('dazk-publico', c); window.DAZK_PUBLICO(c); }, () => {});
  }
  A.resenas().then(l => {
    if (!l.length) return;
    const avg = l.reduce((s, r) => s + r.estrellas, 0) / l.length, st = n => '★'.repeat(n) + '☆'.repeat(5 - n);
    const box = $('#resenas'); box.hidden = false;
    box.innerHTML = `<span class="k">Lo que dicen nuestros clientes</span><p class="avg"><b>${avg.toFixed(1).replace('.', ',')}</b> ${st(Math.round(avg))} <span>${l.length} ${l.length === 1 ? 'opinión' : 'opiniones'}</span></p>
      <div class="rs">${l.map(r => `<figure><div class="st">${st(r.estrellas)}</div>${r.texto ? `<blockquote>${esc(r.texto)}</blockquote>` : ''}<figcaption>${esc(r.nombre)}</figcaption></figure>`).join('')}</div>`;
  }).catch(() => {});

  // ---- visit log for the workshop panel: device, where they came from, what they looked at and how far they got ----
  (function () {
    if (A.load('dazk-ses', null) || A.load('dazk-demo-yo', null) || navigator.webdriver && !window.DAZK_TEST) return; // staff browsing their own site are not visitors
    let v = A.load('dazk-v', null); if (!v) { v = A.rnd(); A.save('dazk-v', v); }
    const id = A.rnd(), w = Math.min(screen.width, screen.height), ref = document.referrer ? new URL(document.referrer).hostname.replace(/^www\./, '') : '';
    const camp = new URLSearchParams(location.search).get('c'), origen = A.canal(camp || (window.DAZK_SHARED ? 'link compartido' : !ref || ref === location.hostname ? 'directo' : ref)) || 'directo';
    if (!A.load('dazk-canal', '')) A.save('dazk-canal', origen); // first touch: the channel that brought them gets the sale
    let sent = { paso: -1 }, first = true, folio = 0;
    function push() {
      const st = window.DAZK_STATE(), paso = [...document.querySelectorAll('.step')].findIndex(s => !s.hidden), nombre = (A.load('dazk-yo', {}).nombre || '').slice(0, 80);
      const now = Object.assign({ v, disp: w < 600 ? 'celular' : w < 1000 ? 'tablet' : 'computadora', origen, paso: Math.max(sent.paso, paso, 0), uso: st.uso }, st.modelo ? { modelo: st.modelo } : {}, nombre ? { nombre } : {}, folio ? { folio } : {});
      if (JSON.stringify(now) === JSON.stringify(sent)) return;
      sent = now; A.visita(id, now, first).catch(() => {}); first = false;
    }
    window.DAZK_VISITA = f => { folio = f; push(); };
    let t; document.addEventListener('click', () => { clearTimeout(t); t = setTimeout(push, 900); });
    setTimeout(push, 1500);
  })();
});
